9	// Service is a delivery speed.
10	type Service int
11	
12	const (
13		Standard Service = iota
14		Express
15	)
16	
17	func (s Service) String() string {
18		switch s {
19		case Standard:
20			return "Standard"
21		case Express:
22			return "Express"
23		}
24		return "Service(" + strconv.Itoa(int(s)) + ")"
25	}
