5	func TestBracketIndex(t *testing.T) {
6		limits := []int{100, 500, 1000}
7		cases := []struct{ v, want int }{
8			{0, 0},
9			{42, 0},
10			{250, 1},
11			{700, 2},
12			{5000, 3},
13		}
14		for _, c := range cases {
15			if got := bracketIndex(limits, c.v); got != c.want {
16				t.Errorf("bracketIndex(%v, %d) = %d, want %d", limits, c.v, got, c.want)
17			}
18		}
19		if got := bracketIndex(nil, 1); got != 0 {
20			t.Errorf("bracketIndex(nil, 1) = %d, want 0", got)
21		}
22	}
