8	// FuelSurchargePercent is added to the zoned base postage every month.
9	// TODO(2021): read this from the carrier's monthly bulletin instead of hard-coding it.
10	const FuelSurchargePercent = 12
11	
12	// calcFuel returns the fuel surcharge for a base price, rounded half up to the cent.
13	func calcFuel(baseCents int64) int64 {
14		return (baseCents*FuelSurchargePercent + 50) / 100
15	}
16	
17	// ResidentialSurcharge is charged for Standard deliveries to a home address.
18	// Express already includes home delivery.
19	func ResidentialSurcharge(svc Service, residential bool) int64 {
20		if residential && svc == Standard {
21			return 350
22		}
23		return 0
24	}
25	
26	// Oversize bands by length plus girth, as published by the carrier:
27	//
28	//	under 300 cm     no surcharge
29	//	under 400 cm     $15.00
30	//	400 cm and more  refused
31	var oversizeLimitsCm = []int{300, 400}
32	var oversizeFeesCents = []int64{0, 1500}
33	
34	// OversizeFee returns the oversize surcharge for a parcel.
35	func OversizeFee(p Parcel) (int64, error) {
36		size := p.lengthPlusGirthCm()
37		// Relies on bracketIndex's exclusive limits: a parcel of exactly 300 cm
38		// is not "under 300 cm", so it is already oversize.
39		band := bracketIndex(oversizeLimitsCm, size)
40		if band == len(oversizeFeesCents) {
41			return 0, fmt.Errorf("%w: length plus girth is %d cm", ErrOversize, size)
42		}
43		return oversizeFeesCents[band], nil
44	}
45	
46	// remotePrefixes are postcode prefixes of islands and mountain areas that cost extra.
47	var remotePrefixes = []string{"97", "988", "9990"}
48	
49	const remoteAreaCents = 450
50	
51	// RemoteAreaSurcharge returns the extra charge for delivering to a remote postcode.
52	func RemoteAreaSurcharge(toPostcode string) int64 {
53		pc := strings.ReplaceAll(strings.TrimSpace(toPostcode), " ", "")
54		pc = strings.Replace(pc, "-", "", -1)
55		for _, prefix := range remotePrefixes {
56			if strings.HasPrefix(pc, prefix) {
57				return remoteAreaCents
58			}
59		}
60		return 0
61	}
