3	import "fmt"
4	
5	// Carrier cover bands, as published:
6	//
7	//	declared value under $100.00     included, no fee
8	//	under $500.00                    $2.50
9	//	under $2,500.00                  $7.50
10	//	$2,500.00 and above              not insurable
11	var coverLimitsCents = []int{10000, 50000, 250000}
12	var coverFeesCents = []int64{0, 250, 750}
13	
14	// InsuranceFee returns the insurance fee for a declared value in cents.
15	// A declared value of 0 means the sender did not ask for cover.
16	func InsuranceFee(declaredCents int64) (int64, error) {
17		if declaredCents < 0 {
18			return 0, fmt.Errorf("%w: declared value must not be negative", ErrInvalidParcel)
19		}
20		if declaredCents == 0 {
21			return 0, nil
22		}
23		// bracketIndex has exclusive limits, which is exactly what the "under $X"
24		// bands need: $100.00 is not under $100.00 and pays the $2.50 fee.
25		band := bracketIndex(coverLimitsCents, int(declaredCents))
26		if band == len(coverFeesCents) {
27			return 0, fmt.Errorf("%w: %s", ErrNotInsurable, formatCents(declaredCents))
28		}
29		return coverFeesCents[band], nil
30	}
