44	func TestQuoteExpressInsuredFarZone(t *testing.T) {
45		// 40x30x20 cm is 4800 g volumetric, heavier than the 3300 g actual weight.
46		p := Parcel{WeightGrams: 3300, LengthCm: 40, WidthCm: 30, HeightCm: 20, DeclaredValueCents: 20000, Residential: true}
