52			t.Errorf("grams=%d zone=%d, want 4800 g, zone 4", q.Grams, q.Zone)
53		}
54		if c, _ := chargeNamed(q, "Postage"); c.Cents != 3184 {
55			t.Errorf("postage = %+v, want 3184", c)
